<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, clearToken, token } from './api.ts'

const route = useRoute(); const router = useRouter()
const loggedIn = ref(!!token()); const username = ref(''); const loginForm = ref({ username: '', password: '' }); const error = ref(''); const loading = ref(false)
const agents = ref<any[]>([]); const selected = ref<any | null>(null); const audit = ref<any[]>([]); const showCreate = ref(false); const createForm = ref({ name: '', username: '', max_devices: 1 }); const createdPassword = ref('')
const showEdit = ref(false); const editForm = ref({ name: '', username: '' })
const dialog = ref({ open: false, title: '', message: '', confirmLabel: '确认', danger: false, inputLabel: '', expected: '', value: '' })
let resolveDialog: ((confirmed: boolean) => void) | undefined
const statusLabel: Record<string, string> = { enabled: '启用', disabled: '禁用', locked: '锁定', suspended: '暂停' }
const pageTitle = computed(() => selected.value ? `代理商 / ${selected.value.name}` : '代理商管理')
async function run(action: () => Promise<any>) { error.value = ''; loading.value = true; try { return await action() } catch (e: any) { if (e.status === 401) { logout(); error.value = '会话已过期，请重新登录' } else error.value = e.message || '请求失败' } finally { loading.value = false } }
async function login() { const admin = await run(() => api.login(loginForm.value.username, loginForm.value.password)); if (admin) { username.value = admin.username; loggedIn.value = true; await router.push('/admin/agents'); await loadAgents() } }
async function loadAgents() { const data = await run(() => api.agents()); if (data) agents.value = Array.isArray(data) ? data : data.items || [] }
async function openAgent(agent: any) { selected.value = await run(() => api.agent(agent.id)); audit.value = await run(() => api.audit(agent.id)) || [] }
async function createAgent() { const data = await run(() => api.createAgent(createForm.value)); if (data) { createdPassword.value = data.password; showCreate.value = false; createForm.value = { name: '', username: '', max_devices: 1 }; await loadAgents() } }
function startEdit() { if (!selected.value) return; editForm.value = { name: selected.value.name, username: selected.value.username }; showEdit.value = true }
async function saveAgent() { if (!selected.value) return; const data = await run(() => api.updateAgent(selected.value.id, editForm.value)); if (data) { showEdit.value = false; await openAgent(selected.value); await loadAgents() } }
function askDialog(options: Partial<typeof dialog.value>) { dialog.value = { open: true, title: '', message: '', confirmLabel: '确认', danger: false, inputLabel: '', expected: '', value: '', ...options }; return new Promise<boolean>((resolve) => { resolveDialog = resolve }) }
function closeDialog(confirmed: boolean) { if (confirmed && dialog.value.expected && dialog.value.value !== dialog.value.expected) return; dialog.value.open = false; resolveDialog?.(confirmed); resolveDialog = undefined }
async function updateStatus(status: string) { if (!selected.value || !await askDialog({ title: '更改账号状态', message: `确认将账号状态改为“${statusLabel[status]}”吗？`, confirmLabel: '确认更改' })) return; await run(() => api.setStatus(selected.value.id, status)); await openAgent(selected.value); await loadAgents() }
async function resetPassword() { if (!selected.value || !await askDialog({ title: '重置代理商密码', message: '重置后将撤销该代理商现有的登录会话。确定继续吗？', confirmLabel: '重置密码', danger: true })) return; const data = await run(() => api.resetCredential(selected.value.id)); if (data) createdPassword.value = data.password }
async function viewPassword() { if (!selected.value || !await askDialog({ title: '查看代理商密码', message: '此次查看操作会记录在审计日志中。确定查看吗？', confirmLabel: '查看密码' })) return; const data = await run(() => api.viewCredential(selected.value.id)); if (data) createdPassword.value = data.password }
async function removeAgent() { if (!selected.value || !await askDialog({ title: '删除代理商', message: '此操作会永久删除账号及其关联历史日志，用户名之后可以重新使用。', confirmLabel: '永久删除', danger: true, inputLabel: `输入用户名 ${selected.value.username} 以确认`, expected: selected.value.username })) return; await run(() => api.deleteAgent(selected.value.id)); selected.value = null; await loadAgents() }
async function logout() { try { if (token()) await api.logout() } catch {} clearToken(); loggedIn.value = false; selected.value = null; createdPassword.value = ''; await router.push('/admin/login') }
onMounted(async () => { if (loggedIn.value) { const me = await run(() => api.me()); if (me) { username.value = me.username; await loadAgents() } } })
</script>

<template>
  <main v-if="route.path === '/admin/login'" class="login-page"><form class="login-card" @submit.prevent="login"><div class="brand">ROBOT <span>管理后台</span></div><h1>管理员登录</h1><label>用户名<input v-model="loginForm.username" autocomplete="username" required /></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required /></label><p v-if="error" class="error">{{ error }}</p><button :disabled="loading">{{ loading ? '登录中…' : '登录' }}</button></form></main>
<main v-else class="shell"><aside><div class="brand">ROBOT <span>管理后台</span></div><nav><a class="active">代理商管理</a></nav></aside><section class="content"><header><div><small>云端管理服务</small><h1>{{ pageTitle }}</h1></div><div class="account">{{ username }} <button class="link" @click="logout">退出</button></div></header><div v-if="error" class="alert">{{ error }}</div><section v-if="!selected" class="panel"><div class="toolbar"><div><h2>代理商</h2><p>管理代理商账号、设备额度与登录状态</p></div><button @click="showCreate = true">+ 创建代理商</button></div><div v-if="!agents.length" class="empty">暂无代理商</div><table v-else><thead><tr><th>名称</th><th>用户名</th><th>状态</th><th>设备</th><th>最后登录</th><th></th></tr></thead><tbody><tr v-for="agent in agents" :key="agent.id"><td>{{ agent.name }}</td><td>{{ agent.username }}</td><td><span :class="['status', agent.status]">{{ statusLabel[agent.status] || agent.status }}</span></td><td>{{ agent.active_devices ?? 0 }} / {{ agent.max_devices }}</td><td>{{ agent.last_login_at ? new Date(agent.last_login_at).toLocaleString() : '从未登录' }}</td><td><button class="link" @click="openAgent(agent)">详情</button></td></tr></tbody></table></section><section v-else class="panel detail"><button class="back link" @click="selected = null">← 返回列表</button><div class="detail-head"><div><h2>{{ selected.name }}</h2><p>{{ selected.username }} · {{ selected.id }}</p></div><span :class="['status', selected.status]">{{ statusLabel[selected.status] }}</span></div><div class="facts"><div><small>创建时间</small><strong>{{ selected.created_at ? new Date(selected.created_at).toLocaleString() : '—' }}</strong></div><div><small>最后登录 IP</small><strong>{{ selected.last_login_ip || '—' }}</strong></div><div><small>设备上限</small><strong>{{ selected.max_devices }}</strong></div></div><div class="actions"><button @click="startEdit">编辑资料</button><button @click="viewPassword">查看密码</button><button @click="resetPassword">重置密码</button><button v-if="selected.status === 'enabled'" @click="updateStatus('disabled')">禁用账号</button><button v-else @click="updateStatus('enabled')">恢复启用</button><button class="danger" @click="removeAgent">删除账号</button></div><h3>关联审计</h3><table><thead><tr><th>事件</th><th>结果</th><th>时间</th><th>来源 IP</th></tr></thead><tbody><tr v-for="item in audit" :key="item.occurred_at + item.event_type"><td>{{ item.event_type }}</td><td>{{ item.result }}</td><td>{{ item.occurred_at }}</td><td>{{ item.source_ip }}</td></tr></tbody></table></section></section><div v-if="showEdit" class="overlay" @click.self="showEdit = false"><form class="modal" @submit.prevent="saveAgent"><button type="button" class="close" aria-label="关闭" @click="showEdit = false">×</button><h2>编辑代理商资料</h2><label>代理商名称<input v-model="editForm.name" maxlength="200" required /></label><label>用户名<input v-model="editForm.username" pattern="[a-z0-9_.-]{3,64}" maxlength="64" required /></label><div class="modal-actions"><button type="button" class="secondary" @click="showEdit = false">取消</button><button :disabled="loading">保存修改</button></div></form></div><div v-if="showCreate" class="overlay" @click.self="showCreate = false"><form class="modal" @submit.prevent="createAgent"><button type="button" class="close" aria-label="关闭" @click="showCreate = false">×</button><h2>创建代理商</h2><label>代理商名称<input v-model="createForm.name" maxlength="200" required /></label><label>用户名<input v-model="createForm.username" pattern="[a-z0-9_.-]{3,64}" maxlength="64" required /></label><label>设备上限<input v-model.number="createForm.max_devices" type="number" min="1" max="10000" required /></label><div class="modal-actions"><button type="button" class="secondary" @click="showCreate = false">取消</button><button :disabled="loading">创建并生成密码</button></div></form></div><div v-if="createdPassword" class="overlay" @click.self="createdPassword = ''"><div class="modal"><button class="close" aria-label="关闭" @click="createdPassword = ''">×</button><h2>凭据已生成</h2><p>请安全交付给代理商，关闭后前端将清除密码。</p><code>{{ createdPassword }}</code><button class="full-width" @click="createdPassword = ''">关闭</button></div></div><div v-if="dialog.open" class="overlay" @click.self="closeDialog(false)" @keydown.esc="closeDialog(false)"><form class="modal" role="alertdialog" aria-modal="true" @submit.prevent="closeDialog(true)"><button type="button" class="close" aria-label="关闭" @click="closeDialog(false)">×</button><h2>{{ dialog.title }}</h2><p>{{ dialog.message }}</p><label v-if="dialog.inputLabel">{{ dialog.inputLabel }}<input v-model="dialog.value" autocomplete="off" /></label><div class="modal-actions"><button type="button" class="secondary" @click="closeDialog(false)">取消</button><button :class="{ danger: dialog.danger }" :disabled="!!dialog.expected && dialog.value !== dialog.expected">{{ dialog.confirmLabel }}</button></div></form></div></main>
</template>
